// Alerte échec workflow n8n -> e-mail. Voir workflows/error-handler.json.
const e = $json || {};
const wf = e.workflow || {};
const ex = e.execution || {};
const err = ex.error || {};
const when = new Date().toISOString();

const subject = `🔴 Jarvis n8n — échec « ${wf.name || wf.id || 'workflow inconnu'} »`;
const body = [
  `Workflow : ${wf.name || '?'} (${wf.id || '?'})`,
  `Horodatage : ${when}`,
  `Nœud en échec : ${ex.lastNodeExecuted || '?'}`,
  `Erreur : ${err.message || 'inconnue'}`,
  ex.id ? `Exécution : ${ex.id}` : '',
  ex.url ? `Lien : ${ex.url}` : '',
  '',
  '— Alerte automatique (workflows/error-handler.json)'
].filter(Boolean).join('\n');

// Destinataire : uniquement via env (multi-tenant, aucun défaut identifiant).
const to = (typeof process !== 'undefined' && (
  process.env.CLIENT_CR_RECIPIENT ||
  process.env.CLIENT_SUMMARY_RECIPIENT ||
  process.env.SUMMARY_RECIPIENT_EMAIL
)) || '';

if (!to) {
  // Pas de destinataire configuré : on log et on s'arrête proprement (pas d'e-mail).
  console.warn('[error-handler] aucun destinataire (CLIENT_CR_RECIPIENT / CLIENT_SUMMARY_RECIPIENT vides)');
  return [];
}
return [{ json: { to, subject, body } }];
